# FfiBknError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class FfiBknError(Exception):
    pass

_UniffiTempFfiBknError = FfiBknError

class FfiBknError:  # type: ignore
    
    class Backend(_UniffiTempFfiBknError):
        
        def __init__(self, message):
            super().__init__(", ".join([
                "message={!r}".format(message),
            ]))
            self.message = message

        def __repr__(self):
            return "FfiBknError.Backend({})".format(str(self))
    _UniffiTempFfiBknError.Backend = Backend # type: ignore
    class TableNotFound(_UniffiTempFfiBknError):
        
        def __init__(self, table):
            super().__init__(", ".join([
                "table={!r}".format(table),
            ]))
            self.table = table

        def __repr__(self):
            return "FfiBknError.TableNotFound({})".format(str(self))
    _UniffiTempFfiBknError.TableNotFound = TableNotFound # type: ignore
    class NotFound(_UniffiTempFfiBknError):
        
        def __init__(self):
            pass

        def __repr__(self):
            return "FfiBknError.NotFound({})".format(str(self))
    _UniffiTempFfiBknError.NotFound = NotFound # type: ignore
    class Encoding(_UniffiTempFfiBknError):
        
        def __init__(self, message):
            super().__init__(", ".join([
                "message={!r}".format(message),
            ]))
            self.message = message

        def __repr__(self):
            return "FfiBknError.Encoding({})".format(str(self))
    _UniffiTempFfiBknError.Encoding = Encoding # type: ignore
    class ReservedTableName(_UniffiTempFfiBknError):
        
        def __init__(self, table):
            super().__init__(", ".join([
                "table={!r}".format(table),
            ]))
            self.table = table

        def __repr__(self):
            return "FfiBknError.ReservedTableName({})".format(str(self))
    _UniffiTempFfiBknError.ReservedTableName = ReservedTableName # type: ignore

FfiBknError = _UniffiTempFfiBknError # type: ignore
del _UniffiTempFfiBknError


class _UniffiFfiConverterTypeFfiBknError(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return FfiBknError.Backend(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 2:
            return FfiBknError.TableNotFound(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 3:
            return FfiBknError.NotFound(
            )
        if variant == 4:
            return FfiBknError.Encoding(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 5:
            return FfiBknError.ReservedTableName(
                _UniffiFfiConverterString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if isinstance(value, FfiBknError.Backend):
            _UniffiFfiConverterString.check_lower(value.message)
            return
        if isinstance(value, FfiBknError.TableNotFound):
            _UniffiFfiConverterString.check_lower(value.table)
            return
        if isinstance(value, FfiBknError.NotFound):
            return
        if isinstance(value, FfiBknError.Encoding):
            _UniffiFfiConverterString.check_lower(value.message)
            return
        if isinstance(value, FfiBknError.ReservedTableName):
            _UniffiFfiConverterString.check_lower(value.table)
            return

    @staticmethod
    def write(value, buf):
        if isinstance(value, FfiBknError.Backend):
            buf.write_i32(1)
            _UniffiFfiConverterString.write(value.message, buf)
        if isinstance(value, FfiBknError.TableNotFound):
            buf.write_i32(2)
            _UniffiFfiConverterString.write(value.table, buf)
        if isinstance(value, FfiBknError.NotFound):
            buf.write_i32(3)
        if isinstance(value, FfiBknError.Encoding):
            buf.write_i32(4)
            _UniffiFfiConverterString.write(value.message, buf)
        if isinstance(value, FfiBknError.ReservedTableName):
            buf.write_i32(5)
            _UniffiFfiConverterString.write(value.table, buf)






class FfiDirection(enum.Enum):
    
    OUT = 0
    
    IN = 1
    
    BOTH = 2
    


class _UniffiFfiConverterTypeFfiDirection(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return FfiDirection.OUT
        if variant == 2:
            return FfiDirection.IN
        if variant == 3:
            return FfiDirection.BOTH
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == FfiDirection.OUT:
            return
        if value == FfiDirection.IN:
            return
        if value == FfiDirection.BOTH:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == FfiDirection.OUT:
            buf.write_i32(1)
        if value == FfiDirection.IN:
            buf.write_i32(2)
        if value == FfiDirection.BOTH:
            buf.write_i32(3)



