class BknDbEngineProtocol(typing.Protocol):
    """
    The main mobile entrypoint for BknDb, thread-safe and exported via UniFFI.
"""
    
    def cascade_delete(self, root: int,containment_edge: str) -> typing.List[int]:
        """
        Recursively cascade-deletes `root` and all descendants reachable via `containment_edge`.
"""
        raise NotImplementedError
    def create_edge(self, _from: int,edge_type: str,to: int,properties: dict[str, FfiPropValue]) -> int:
        """
        Creates a directed edge between two existing nodes.
"""
        raise NotImplementedError
    def create_edges_bulk(self, edges: typing.List[FfiEdgeInput]) -> typing.List[int]:
        """
        Creates multiple edges in a single atomic transaction.
"""
        raise NotImplementedError
    def create_node(self, label: str,properties: dict[str, FfiPropValue]) -> int:
        """
        Creates a single graph node with the given label and properties.
"""
